1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/dmi_poll.hpp"
9	#include "hybrid/resume_driver.hpp"
10	#include "hybrid/state_abi.h"
11	#include "hybrid/v_regfile_xfer.hpp"
12	
13	#include <algorithm>
14	#include <cstdint>
15	
16	namespace hybrid
17	{
18	
19	class StateDrain
20	{
21	public:
22	  using RD = ResumeDriver;
23	
24	  explicit StateDrain(DmiBus& bus)
25	      : bus_{bus}
26	  {}
27	
28	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
29	  // drain_with_passthrough when the QEMU 1 snapshot is available.
30	  auto drain() -> hybrid_state_v1
31	  {
32	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
33	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
34	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
35	                   "StateDrain halt");
36	
37	    hybrid_state_v1 state{};
38	    state.magic   = HYBRID_STATE_MAGIC;
39	    state.version = HYBRID_STATE_VERSION;
40	    state.flags   = HYBRID_FLAG_RV64;
41	    state.priv    = 3;
42	
43	    for (uint16_t i = 1; i < 32; ++i)
44	      state.gpr[i] = read_64bit_register(regno_gpr(i));
45	
46	    state.pc = read_64bit_register(regno_csr(RD::kCsrDpc));
47	    return state;
48	  }
49	
50	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
51	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 so
52	  // post-vsim FP modifications are captured (otherwise the stale QEMU 1
53	  // snapshot leaks through to QEMU 2). When HYBRID_FLAG_V is set, also
54	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
55	  // and vreg remain pass-through (read-only / too large for DM).
56	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
57	  // contribution would otherwise be discarded as the passthrough preserves
58	  // QEMU1's pre-handoff value.
59	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
60	  {
61	    auto state       = input;
62	    const auto fresh = drain();
63	    std::copy(std::begin(fresh.gpr) + 1, std::end(fresh.gpr),
64	              std::begin(state.gpr) + 1);
65	    state.pc = fresh.pc;
66	
67	    if (input.flags & HYBRID_FLAG_FP) {
68	      for (uint16_t i = 0; i < 32; ++i)
69	        state.fpr[i] = read_64bit_register(regno_fpr(i));
70	    }
71	
72	    if (input.flags & HYBRID_FLAG_V) {
73	      state.vstart = read_64bit_register(regno_csr(RD::kCsrVstart));
74	      state.vxsat  = read_64bit_register(regno_csr(RD::kCsrVxsat));
75	      state.vxrm   = read_64bit_register(regno_csr(RD::kCsrVxrm));
76	      state.vcsr   = read_64bit_register(regno_csr(RD::kCsrVcsr));
77	      state.vtype  = read_64bit_register(regno_csr(RD::kCsrVtype));
78	      state.vl     = read_64bit_register(regno_csr(RD::kCsrVl));
79	    }
80	
81	    state.mcycle   = read_64bit_register(regno_csr(RD::kCsrMcycle));
82	    state.minstret = read_64bit_register(regno_csr(RD::kCsrMinstret));
83	
84	    // V data regfile: dump v0..v31 to the shared scratch region via the
85	    // Program Buffer LAST -- after every architectural read above -- so the
86	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
87	    // cannot corrupt the values already captured. The simulator's
88	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
89	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
90	    if (input.flags & HYBRID_FLAG_V)
91	      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, input.vlenb,
92	                      /*load=*/false);
93	
94	    return state;
95	  }
96	
97	private:
98	  auto read_64bit_register(uint16_t regno) -> uint64_t
99	  {
100	    bus_.write(RD::kCommand, access_register_command(regno, AarSize::Bits64,
101	                                                     /*write=*/false));
102	    poll_until_clear(bus_, RD::kAbstractcs, RD::kAbstractcsBusy,
103	                     "StateDrain read_register");
104	    // If the hardware DM does not implement Abstract access for this
105	    // register, cmderr is set sticky and DATA0/DATA1 hold stale bytes.
106	    // Clear the error and report 0 for that field so the next read can
107	    // proceed - a missing CSR mirrors as zero rather than corrupting the
108	    // adjacent slot.
109	    const auto status = bus_.read(RD::kAbstractcs);
110	    if ((status & RD::kAbstractcsCmderrMask) != 0u) {
111	      bus_.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
112	      return 0u;
113	    }
114	    const uint64_t lo = bus_.read(RD::kData0);
115	    const uint64_t hi = bus_.read(RD::kData1);
116	    return lo | (hi << 32);
117	  }
118	
119	  DmiBus& bus_;
120	};
121	
122	}  // namespace hybrid
