199	  // Caller invariant: the CPU must already be out of reset.
200	  void apply_resume_from_qemu(const std::string& path)
201	  {
202	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
203	      bus{platform.dmi, platform.clk.period()};
204	    hybrid_input_state_ = hybrid::load_state(path);
205	    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
206	    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
207	    // this region to repopulate v0..v31, so the bytes must be in place first.
208	    // Best-effort: mismatched RAM layouts throw, which is louder than silently
209	    // dropping V state.
210	    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
211	      hybrid::stage_v_to_scratch(
212	        *hybrid_input_state_,
213	        platform.main_memory.data,
214	        platform.main_memory.region.base_address);
215	    }
216	    hybrid::ResumeDriver driver(bus);
217	    driver.resume(*hybrid_input_state_);
218	  }
219	
220	  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
221	  // committed PCs and on retire of a `csrw 0x7C0, *` exit-trigger drains
222	  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
223	  //
224	  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
225	  // mode) and the ELF scan is skipped: the binary need not contain a magic
226	  // csrwi marker. CSR mode and PC mode are mutually exclusive on a single
227	  // run -- callers pass exactly one form.
228	  void enable_hybrid_handoff(const std::string& elf_path,
229	                             const std::string& state_out_path,
230	                             std::optional<uint64_t> exit_pc = std::nullopt)
231	  {
232	    hybrid::CsrTrigger trigger;
233	    if (exit_pc) {
234	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
235	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
236	    } else {
237	      auto elf = LIEF::ELF::Parser::parse(elf_path);
238	      if (!elf)
239	        throw std::runtime_error(
240	          "enable_hybrid_handoff: failed to parse " + elf_path);
241	      for (const auto& seg: elf->segments()) {
242	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
243	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
244	        const auto content = seg.content();
245	        const std::span<const uint8_t> bytes{content.data(), content.size()};
246	        trigger.scan_buffer(bytes, seg.virtual_address());
247	      }
248	    }
249	
250	    hybrid_dmi_bus_ = std::make_unique<
251	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
252	                            PLATFORM::dmi_data_width>>(platform.dmi,
253	                                                       platform.clk.period());
254	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_);
255	    if (hybrid_input_state_)
256	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
257	    hybrid_state_path_ = state_out_path;
258	  }
259	
260	  // icount-trigger variant: drain after `target` committed insns retire,
261	  // regardless of PC. Sibling to enable_hybrid_handoff (which is CSR/PC). The
262	  // two modes are mutually exclusive on a single run -- callers pass at most
263	  // one. Multi-hart out of scope per F6: the trigger counts hart-0 retires.
264	  void enable_hybrid_icount_handoff(const std::string& state_out_path,
265	                                    uint64_t icount_target)
266	  {
267	    hybrid::IcountTrigger trigger{icount_target};
268	    spdlog::info("hybrid: icount-trigger mode, target={}", icount_target);
269	
270	    hybrid_dmi_bus_ = std::make_unique<
271	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
272	                            PLATFORM::dmi_data_width>>(platform.dmi,
273	                                                       platform.clk.period());
274	    hybrid_icount_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_);
275	    if (hybrid_input_state_)
276	      hybrid_icount_handoff_->set_passthrough_input(*hybrid_input_state_);
277	    hybrid_state_path_ = state_out_path;
278	  }
279	
280	  void restore_context(const std::string& dir)
281	  {
282	    context_config.dir = dir;
283	    context_config.restore(platform, cpu);
284	  }
285	
286	  void save_context(const std::string& dir)
287	  {
288	    context_config.dir = dir;
289	    context_config.save(platform, cpu);
290	  }
291	
292	  // skip_memory_load: parse the ELF and set the reset vector, but leave
293	  // platform.main_memory untouched. Used in tier-2 hybrid resume where
294	  // QEMU 1's -kernel already populated the shared mmap; re-loading would
295	  // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
296	  // to static buffers. The reset vector is still set so the hart has a
297	  // valid fetch target during the post-reset cycles that precede the DMI
298	  // halt+DPC-write resume sequence.
299	  void load_elf(const std::string& path, bool skip_memory_load = false)
300	  {
301	    const auto elf = LIEF::ELF::Parser::parse(path);
302	    if (!elf) {
303	      spdlog::critical("Check if it's a valid ELF file path : {}", path);
304	      exit(1);
305	    }
306	
307	    if (!skip_memory_load)
308	      read_elf_into_memory(
309	        *elf,
310	        static_cast<xlen_t>(platform.main_memory.region.base_address),
311	        platform.main_memory.data);
312	    for (auto& rv: platform.reset_vector)
313	      rv.write(elf->entrypoint());
314	  }
315	
316	  void set_reset_vector(size_t hart, uint64_t addr)
317	  {
318	    if (hart >= platform.reset_vector.size()) {
319	      spdlog::critical("hart {} out of range (max {})", hart,
320	                       platform.reset_vector.size() - 1);
321	      std::exit(EXIT_FAILURE);
322	    }
323	    platform.reset_vector[hart].write(addr);
324	  }
325	
326	  void load_image(const std::string& path, MEM_TYPE type)
327	  {
328	    switch (type) {
329	    case MEM_TYPE::ILM:
330	      if constexpr (requires { cpu.set_ilm({}); }) {
331	        read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
332	      } else {
333	        throw std::runtime_error(
334	          "CPU does not support ILM - cannot load ILM ROM image");
335	      }
336	      break;
337	
338	    case MEM_TYPE::DLM:
339	      if constexpr (requires { cpu.set_dlm({}); }) {
340	        read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
341	      } else {
342	        throw std::runtime_error(
343	          "CPU does not support DLM - cannot load DLM ROM image");
344	      }
345	      break;
346	
347	    case MEM_TYPE::RAM:
348	      read_binary_file(path, [this](const auto& data) {
349	        if (data.size() > platform.main_memory.data.size())
350	          throw std::runtime_error("RAM image size exceeds main memory size");
351	        std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
352	      });
353	      break;
354	
355	    default:
356	      throw std::runtime_error("Unknown memory type");
357	    }
358	  }
359	
360	  void reset()
361	  {
362	    static constexpr int core_num = CPU::NDS_NHART;
363	    static constexpr int reset_val = (1 << core_num) - 1;
364	
365	    platform.resetn.write(0);
366	    auto saved = context_config;
367	    context_config = {};
368	    this->run(1);
369	    context_config = saved;
370	
371	    for (size_t i = 0; i < platform.reset_vector.size(); ++i)
372	      spdlog::info("hart {} reset vector: {:#x}", i,
373	                   (uint64_t) platform.reset_vector[i].read());
374	
375	    platform.resetn.write(reset_val);
376	
377	    if (context_config.continue_from)
378	      restore_context(context_config.dir);
379	  }
380	
381	  int run(const uint64_t max_cycles = std::numeric_limits<uint64_t>::max())
382	  {
383	    auto sa = memzeroed<struct sigaction>();
384	    sa.sa_handler = sigint_handler;
385	    sigemptyset(&sa.sa_mask);
386	
387	    auto oact = memzeroed<struct sigaction>();
388	    if (sigaction(SIGINT, &sa, &oact) == -1)
389	      perror("sigaction");
390	
391	    const auto restore_sigint = std::experimental::scope_exit{[&] {
392	      if (sigaction(SIGINT, &oact, nullptr) == -1)
393	        perror("sigaction");
394	    }};
395	
396	    // wait for debugger connections
397	    while (dtm_debug && !dtm.is_connected()) {
398	      dtm.try_accept_socket();
399	      if (ctrlc != 0) {
400	        return 130;
401	      }
402	      sleep(1);
403	    }
404	
405	    [[maybe_unused]]
406	    bool ctx_resuming = context_config.continue_from;
407	    [[maybe_unused]]
408	    bool ctx_triggered = false;
409	
410	    for (auto n = uint64_t{0}; n < max_cycles; ++n) {
411	
412	      if (ctx_resuming) [[unlikely]] {
413	        // Pull up PLIC interrupt signal at the first cycle of the resume
414	        platform.int_trigger.write(1);
415	        ctx_resuming = false;
416	        ctx_triggered = true;
417	      }
418	
419	      sc_core::sc_start(platform.clk.period());
420	
421	      trace_.on_cycle(cpu);
422	
423	      if (hybrid_handoff_ || hybrid_icount_handoff_) [[unlikely]] {
424	        if (auto code = check_hybrid_handoff(); code) return *code;
425	      }
426	
427	      if (trace_.pipeview_wants_exit()) {
428	        spdlog::info("Pipeline viewer requested exit (Kanata loop window complete)");
429	        return 0;
430	      }
431	
432	      if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
433	        [[unlikely]]
434	      {
435	        context_config.save(platform, cpu);
436	        spdlog::info("User save context");
437	        return 0;
438	      }
439	
440	      if (ctrlc != 0) {
441	        ctrlc = 0;
442	        spdlog::info("Ctrl+C PC: {:x}", get_current_pc());
443	        trace_.log_committed_pcs(cpu);
444	        return 130;
445	      }
446	
447	      if (ctx_triggered) [[unlikely]] {
448	        // Pull down the interrupt signal after 1 cycle
449	        platform.int_trigger.write(0);
450	        ctx_triggered = false;
451	      }
452	
453	      if (platform.sim_control.exits >= 0) {
454	        spdlog::info("sim_control: got exit {}, stopping",
455	                     platform.sim_control.exits);
456	        spdlog::info("Exit PC: {:x}", get_current_pc());
457	        trace_.log_committed_pcs(cpu);
458	        return platform.sim_control.exits;
459	      }
460	
461	      if (this->cpu.contextp()->gotFinish())
462	        return 0;
463	
464	      spdlog::trace("PC: {:x}", get_current_pc());
465	    }
466	    return 0;
467	  }
468	
469	  uint64_t get_current_pc()
470	  {
471	    if constexpr (requires { cpu.get_current_pc(); }) {
472	      return cpu.get_current_pc();
473	    }
474	    return std::numeric_limits<uint64_t>::max();
475	  }
476	
477	  auto check_hybrid_handoff() -> std::optional<int>
478	  {
479	    if constexpr (!requires { cpu.get_committed_pc(); }) {
480	      return std::nullopt;
481	    } else {
482	      const auto committed = cpu.get_committed_pc();
483	      if (committed.empty()) return std::nullopt;
484	      auto gpr_probe = [&](uint8_t r) -> uint64_t {
485	        if constexpr (requires { cpu.get_gpr(r); }) {
486	          return cpu.get_gpr(r);
487	        }
488	        return 0;
489	      };
490	      for (const auto pc: committed[0]) {
491	        auto state = std::optional<hybrid_state_v1>{};
492	        if (hybrid_handoff_)
493	          state = hybrid_handoff_->on_retire(pc, gpr_probe);
494	        else if (hybrid_icount_handoff_)
495	          state = hybrid_icount_handoff_->on_retire(pc, gpr_probe);
496	        if (state) {
497	          // V-register merge: the fixture's vsim-phase epilogue is expected
498	          // to have run vse8.v v0..v31 to scratch RAM before the exit
499	          // trigger fired. Read those bytes back into state.vreg[] so the
500	          // gdbstub-driven QEMU 2 restore sees vsim's actual values, not
501	          // QEMU 1's stale snapshot.
502	          if ((state->flags & HYBRID_FLAG_V) != 0u) {
503	            hybrid::read_v_from_scratch(
504	              *state,
505	              std::span<const uint8_t>{platform.main_memory.data.data(),
506	                                       platform.main_memory.data.size()},
507	              platform.main_memory.region.base_address);
508	          }
509	          spdlog::info("hybrid handoff: drained at pc=0x{:x}, writing {}",
510	                       pc, hybrid_state_path_);
511	          std::ofstream f(hybrid_state_path_, std::ios::binary);
512	          f.write(reinterpret_cast<const char*>(&*state), sizeof(*state));
513	          return hybrid::kExitHandoffToQemu;
514	        }
515	      }
516	      return std::nullopt;
517	    }
518	  }
519	
520	  void enable_waveform(const std::string& waveform_filename)
521	  {
522	    trace_.enable_waveform(cpu, waveform_filename);
523	  }
524	
525	  void enable_pc_trace(const std::string& filename)
526	  {
527	    trace_.enable_pc_trace(filename);
528	  }
529	
530	  void disable_pc_trace() { trace_.disable_pc_trace(); }
531	
532	  void enable_kanata(const std::string& filename,
533	                     const std::string& objdump_file = "",
534	                     std::optional<kanata::LoopGate> gate = std::nullopt)
535	  {
536	    trace_.enable_kanata(cpu, filename, objdump_file, gate);
537	  }
538	
539	  void enable_clarity(const std::string& filename,
540	                      const std::string& objdump_file = "",
541	                      std::optional<kanata::LoopGate> gate = std::nullopt)
542	  {
543	    trace_.enable_clarity(cpu, filename, objdump_file, gate);
544	  }
545	
546	  // Auto-derive the kanata LoopGate from the active hybrid state:
547	  //   start_pc = resume PC (from hybrid_input_state_->pc)
548	  //   end_pc   = explicit_exit_pc when set (pc-mode -- the --hybrid-exit-pc
549	  //              CLI value), otherwise the unique HYBRID_HANDOFF_EXIT PC
550	  //              scanned by the CsrTrigger (csr-mode).
551	  // Must be called AFTER apply_resume_from_qemu and enable_hybrid_handoff,
552	  // so the resume PC and the CsrTrigger are populated.
553	  void enable_kanata_roi(const std::string& filename,
554	                         const std::string& objdump_file,
555	                         std::optional<uint64_t> explicit_exit_pc)
556	  {
557	    if (!hybrid_input_state_)
558	      throw std::runtime_error(
559	        "--kanata-roi requires --resume-from-qemu (no resume PC available)");
560	    if (!hybrid_handoff_)
561	      throw std::runtime_error(
562	        "--kanata-roi requires CSR or PC trigger mode "
563	        "(incompatible with --hybrid-icount)");
564	    const auto gate = hybrid::derive_roi_kanata_gate(
565	      hybrid_handoff_->trigger(), hybrid_input_state_->pc, explicit_exit_pc);
566	    spdlog::info(
567	      "kanata-roi: window start=0x{:x} end=0x{:x} (skip=0 record=1)",
568	      gate.start_pc, gate.end_pc);
569	    trace_.enable_kanata(cpu, filename, objdump_file, gate);
570	  }
571	
572	  void disable_pipeview() { trace_.disable_pipeview(); }
573	
574	  void dump_cycle_pcs() { trace_.dump_cycle_pcs(cpu); }
575	
576	  auto get_cycles() -> std::uint64_t { return trace_.get_cycles(platform.clk); }
577	
578	  auto get_exits() { return platform.sim_control.exits; }
579	
580	  void log_committed_pcs() { trace_.log_committed_pcs(cpu); }
581	
582	  void set_mem_latency(const uint32_t latency)
583	  {
584	    platform.main_memory.latency = latency;
585	  }
586	
587	  void close_trace() { trace_.close(); }
588	
589	#if ENABLE_PYBIND11
590	  static void bind_pybind11(pybind11::module_& m, const char* name)
591	  {
592	    namespace py = pybind11;
593	    auto c = py::class_<Simulator<CPU>>(m, name);
594	    c.def(py::init([](const char* name) { return new Simulator<CPU>(name); }));
595	    c.def("init_debug_port", &Simulator<CPU>::init_debug_port);
596	    c.def("load_elf", &Simulator<CPU>::load_elf);
597	    c.def("get_cycles", &Simulator<CPU>::get_cycles);
598	    c.def("reset", &Simulator<CPU>::reset);
599	    c.def("set_mem_latency", &Simulator<CPU>::set_mem_latency);
600	    c.def("get_exits", &Simulator<CPU>::get_exits);
601	    c.def("run", &Simulator<CPU>::run, "",
602	          py::arg("max_cycles") = std::numeric_limits<uint64_t>::max());
603	    c.def_readonly("cpu", &Simulator<CPU>::cpu,
604	                   py::return_value_policy::reference);
605	  }
606	#endif
607	};
