164	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
165	    write_64bit_register(regno_gpr(scratch_gpr), value);
166	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
167	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
168	  }
169	
170	  // Write a CSR-addressable register and clear any cmderr the DM raised.
171	  // Used for CSRs whose abstract-access support may be implementation
172	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
173	  // remaining writes.
174	  void write_csr_tolerant(uint16_t csr, uint64_t value)
175	  {
176	    write_64bit_register(regno_csr(csr), value);
177	    clear_cmderr_if_set();
178	  }
179	
180	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
181	  // is rejected until the bits are W1C-cleared. We tolerate per-register
182	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
183	  // error before resuming so the hart isn't left in a stuck state.
184	  void clear_cmderr_if_set()
185	  {
186	    const auto status = bus_.read(kAbstractcs);
187	    if ((status & kAbstractcsCmderrMask) != 0u)
188	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
189	  }
190	
